-- Rewrite personal-data CMS page to short CS notice.
-- Regenerated from packages/api/src/cmsPersonalDataSeedContent.ts (cs).
--
-- Locale guard (one language per D1 / deployment — see docs/i18n-prep.md):
-- Applies only when admin_settings.ui_locale = 'cs'.
-- Operators must set that key explicitly before migrate (documented setup step;
-- no email-based bootstrap). Other locales leave this page unchanged.
-- Safe to ship all three migrations together.

UPDATE cms_pages
SET title = 'Osobní údaje a soukromí',
    description = 'Stručný přehled toho, jaká data o vás ukládáme a proč — pro předplatitele v EU, zejména v Česku a na Slovensku.',
    content = '[{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tuto službu provozujeme pro předplatitele v EU, zejména v Česku a na Slovensku. Níže je stručný přehled toho, jaká data o vás ukládáme a proč."}]},{"type":"paragraph","content":[{"type":"text","text":"Tato stránka vás neblokuje ani nenutí k rozhodnutí — je jen informační. Dokud se nepřihlásíte, nekoupíte si předplatné nebo nezměníte nastavení přehrávače (například rychlost přehrávání), žádná data nad rámec technického minima o vás neukládáme."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Nepřihlášení uživatelé"}]},{"type":"paragraph","content":[{"type":"text","text":"Bez přihlášení si můžete prohlížet veřejné stránky a náhledy videí, aniž bychom cokoliv ukládali ve vašem prohlížeči. Návštěvnost měříme anonymně přes Umami (EU) — bez cookies, bez sledování napříč weby."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Aktivní funkce"}]},{"type":"paragraph","content":[{"type":"text","text":"Přihlášení, předplatné, notifikace, instalace webové aplikace (PWA) nebo změna rychlosti přehrávání vyžadují uložení malého množství dat v prohlížeči. Bez využití těchto funkcí se jejich ukládání zcela vyhnete."}]}]}},{"type":"table","columns":["Co","K čemu","Jak dlouho"],"columnKeys":["what","purpose","lifetime"],"rows":[{"what":"refresh_token","purpose":"udrží vás přihlášené","lifetime":"max. 30 dní / do odhlášení"},{"what":"playbackRate","purpose":"zapamatuje si rychlost přehrávání","lifetime":"do vymazání dat webu"},{"what":"nuxt-color-mode","purpose":"světlý/tmavý režim","lifetime":"do vymazání dat webu"},{"what":"vmp_pwa_device_token, vmp_pwa_login_email, vmp-pwa-auth","purpose":"přihlášení přes nainstalovanou iOS appku","lifetime":"do odhlášení / vymazání"},{"what":"cache service workeru","purpose":"rychlejší načítání appky offline","lifetime":"dokud je appka nainstalovaná"},{"what":"data relace (sessionStorage)","purpose":"bezpečnost během přihlašování","lifetime":"do zavření karty"},{"what":"vmp_personal_data_notice_ack","purpose":"aby se vám tento banner nezobrazoval opakovaně","lifetime":"do vymazání dat webu"}]},{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nic z toho nepoužíváme na reklamu ani profilování."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Kdo s daty pracuje"}]},{"type":"paragraph","content":[{"type":"text","text":"Hosting běží na Cloudflare (případně záložně na Deno Deploy / Vercel). Platby řeší Stripe, e-maily Brevo, chyby aplikace sledujeme přes Sentry, návštěvnost přes Umami (EU). Každý z nich vidí jen data potřebná pro svůj úkol."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sledování přehrávání"}]},{"type":"paragraph","content":[{"type":"text","text":"Pokud jste přihlášeni, ukládáme si, kde jste video naposledy přestali sledovat, abyste mohli pokračovat. Tuto pozici můžete kdykoliv smazat v sekci „Pokračovat ve sledování“ ve svém účtu."}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Vaše práva"}]},{"type":"paragraph","content":[{"type":"text","text":"Máte právo na přístup ke svým údajům, jejich opravu, výmaz, omezení zpracování nebo přenos jinam. Stačí napsat na vmp@tjm.sk — včetně žádosti o úplné smazání účtu."}]},{"type":"paragraph","content":[{"type":"text","text":"Pokud nejste spokojeni s tím, jak vaši žádost vyřídíme, můžete se obrátit na:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Česko — ÚOOÚ (uoou.cz)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Slovensko — ÚOO SR (dataprotection.gov.sk)"}]}]}]}]}},{"type":"rich_text","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tuto stránku můžeme časem aktualizovat; aktuální verze je vždy zde."}]}]}}]',
    updated_at = CURRENT_TIMESTAMP
WHERE id = 'cms-page-personal-data'
  AND EXISTS (
    SELECT 1 FROM admin_settings
    WHERE key = 'ui_locale' AND TRIM(value) = 'cs'
  );
